/**
 * Get exact centroid coordinates for a given village/desa
 */
export function getDesaCoordinates(
  kecamatanId?: string,
  villageName?: string
): { lat: number; lng: number; name: string; kecamatanName: string; adm4Code: string } | null {
  if (!villageName) return null;
  const clean = villageName.toLowerCase().trim();

  // 1. Try with kecamatanId prefix
  if (kecamatanId) {
    const direct = BANYUMAS_DESA_MAP[kecamatanId + '_' + clean];
    if (direct) {
      return {
        lat: direct.lat,
        lng: direct.lng,
        name: direct.name,
        kecamatanName: direct.kecamatanName,
        adm4Code: direct.adm4Code,
      };
    }
  }

  // 2. Try global village name
  const global = BANYUMAS_DESA_MAP[clean];
  if (global) {
    return {
      lat: global.lat,
      lng: global.lng,
      name: global.name,
      kecamatanName: global.kecamatanName,
      adm4Code: global.adm4Code,
    };
  }

  // 3. Partial / normalized search (without prefix 'desa', 'kelurahan', 'kel.', 'ds.')
  const normalized = clean.replace(/^(desa|kelurahan|kel.|ds.)s+/i, '').trim();
  if (kecamatanId) {
    const normDirect = BANYUMAS_DESA_MAP[kecamatanId + '_' + normalized];
    if (normDirect) {
      return {
        lat: normDirect.lat,
        lng: normDirect.lng,
        name: normDirect.name,
        kecamatanName: normDirect.kecamatanName,
        adm4Code: normDirect.adm4Code,
      };
    }
  }

  const normGlobal = BANYUMAS_DESA_MAP[normalized];
  if (normGlobal) {
    return {
      lat: normGlobal.lat,
      lng: normGlobal.lng,
      name: normGlobal.name,
      kecamatanName: normGlobal.kecamatanName,
      adm4Code: normGlobal.adm4Code,
    };
  }

  return null;
}

/**
 * Find the nearest desa from GPS coordinates using distance squared approximation
 */
export function findNearestDesaFromCoords(lat: number, lng: number): DesaSpatialInfo | null {
  let closest: DesaSpatialInfo | null = null;
  let minDistSq = Infinity;

  for (const d of ALL_BANYUMAS_DESA) {
    const dLat = (d.lat - lat) * 111320;
    const dLng = (d.lng - lng) * 110574;
    const distSq = dLat * dLat + dLng * dLng;
    if (distSq < minDistSq) {
      minDistSq = distSq;
      closest = d;
    }
  }

  return closest;
}
